mapper.insert:
INSERT INTO PLAN_LIKE (
	PLAN_LIKE_ID,
	PLAN_ID,
	MEMBER_ID
) VALUES (
	SEQ_PLAN_LIKE.NEXTVAL,
	#{planId},
	#{memberId}
)

mapper.delete:
DELETE FROM PLAN_LIKE
 WHERE PLAN_ID = #{planId}
   AND MEMBER_ID = #{memberId}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
  FROM PLAN_LIKE
 WHERE PLAN_ID = #{planId}
   AND MEMBER_ID = #{memberId}
